import fs from 'node:fs';
import { parseDeck } from './src/deck.mjs';
const raw=fs.readFileSync('courses/reading-data-and-evidence.json','utf8');
const deck=parseDeck(raw);
if (deck.items.length!==12 || deck.concepts.length!==4) throw Error('Course count mismatch');
if (!Object.isFrozen(deck) || !deck.items.every(Object.isFrozen)) throw Error('Validator snapshot is not frozen');
console.log(JSON.stringify({accepted:true,format:deck.format,title:deck.title,items:deck.items.length,concepts:deck.concepts.length,utf8_bytes:Buffer.byteLength(raw)}));
